/* All three declarations represent an identical vibrant blue with 80% opacity */

/* 1. Hexadecimal with alpha (#RRGGBBAA) */
.box-hex {
  background-color: #2563ebcc;
}

/* 2. Modern RGB syntax (red green blue / alpha) */
.box-rgb {
  background-color: rgb(37 99 235 / 0.8);
}

/* 3. Modern HSL syntax (hue saturation lightness / alpha) */
.box-hsl {
  background-color: hsl(221 83% 53% / 0.8);
}

/* 1. Linear Gradient angled at 135 degrees with 3 color stops */
.hero-gradient-linear {
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #ec4899 100%);
  min-height: 250px;
  border-radius: 12px;
}

/* 2. Radial Gradient emanating from the center */
.spotlight-radial {
  background: radial-gradient(circle at center, #38bdf8 0%, #0369a1 70%, #0f172a 100%);
  min-height: 250px;
  border-radius: 12px;
}

.hero-banner {
  /* Image URL and overlay gradient for text contrast */
  background-image: 
    linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)),
    url('https://images.unsplash.com/photo-1517694712202-14dd9538aa97');

  /* Scales image to completely cover the container while preserving aspect ratio */
  background-size: cover;

  /* Centers the focal point of the image */
  background-position: center center;

  /* Prevents tiling/duplication */
  background-repeat: no-repeat;

  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
}
